import "server-only";
import fs from "node:fs";
import path from "node:path";
import { cache } from "react";

type PathologyIndexItem = { slug: string; name: string };

// Generated by prepare-site before dev/build. Dynamic routes must not import
// pathology-content: its directory scans pull all original images into bundles.
export const getPathologyIndex = cache((): PathologyIndexItem[] => {
  const file = path.join(process.cwd(), ".generated", "catalog.json");
  const catalog = JSON.parse(fs.readFileSync(file, "utf8")) as PathologyIndexItem[];
  return catalog.map(({ slug, name }) => ({ slug, name }));
});
